INSERT INTO `translations` (`id`, `lang`, `lang_key`, `lang_value`, `created_at`, `updated_at`) VALUES
(1796, 'en', 'Please be carefull when you are configuring Facebook pixel.', 'Please be carefull when you are configuring Facebook pixel.', '2022-12-11 12:36:18', '2022-12-11 12:36:18'),
(1797, 'en', 'Log in to Facebook and go to your Ads Manager account', 'Log in to Facebook and go to your Ads Manager account', '2022-12-11 12:36:18', '2022-12-11 12:36:18'),
(1798, 'en', 'Open the Navigation Bar and select Events Manager', 'Open the Navigation Bar and select Events Manager', '2022-12-11 12:36:18', '2022-12-11 12:36:18'),
(1799, 'en', 'Copy your Pixel ID from underneath your Site Name and paste the number into Facebook Pixel ID field', 'Copy your Pixel ID from underneath your Site Name and paste the number into Facebook Pixel ID field', '2022-12-11 12:36:18', '2022-12-11 12:36:18'),
(1800, 'en', 'Google Analytics Setting', 'Google Analytics Setting', '2022-12-11 12:36:18', '2022-12-11 12:36:18'),
(1801, 'en', 'Google Analytics', 'Google Analytics', '2022-12-11 12:36:18', '2022-12-11 12:36:18'),
(1802, 'en', 'Tracking ID', 'Tracking ID', '2022-12-11 12:36:18', '2022-12-11 12:36:18'),
(1803, 'en', 'At the very bottom, you can find the “Facebook Page ID”', 'At the very bottom, you can find the “Facebook Page ID”', '2022-12-11 12:36:27', '2022-12-11 12:36:27'),
(1804, 'en', 'Go to Settings of your page and find the option of \"Advance Messaging\"', 'Go to Settings of your page and find the option of \"Advance Messaging\"', '2022-12-11 12:36:27', '2022-12-11 12:36:27'),
(1805, 'en', 'Scroll down that page and you will get \"white listed domain\"', 'Scroll down that page and you will get \"white listed domain\"', '2022-12-11 12:36:27', '2022-12-11 12:36:27'),
(1806, 'en', 'Facebook Comment Setting', 'Facebook Comment Setting', '2022-12-11 12:36:34', '2022-12-11 12:36:34'),
(1807, 'en', 'Facebook App ID', 'Facebook App ID', '2022-12-11 12:36:34', '2022-12-11 12:36:34'),
(1808, 'en', 'Please be carefull when you are configuring Facebook Comment. For incorrect configuration you will not get comment section on your user-end site.', 'Please be carefull when you are configuring Facebook Comment. For incorrect configuration you will not get comment section on your user-end site.', '2022-12-11 12:36:34', '2022-12-11 12:36:34'),
(1809, 'en', 'After then go to this URL https://developers.facebook.com/apps/', 'After then go to this URL https://developers.facebook.com/apps/', '2022-12-11 12:36:34', '2022-12-11 12:36:34'),
(1810, 'en', 'Create Your App', 'Create Your App', '2022-12-11 12:36:34', '2022-12-11 12:36:34'),
(1811, 'en', 'In Dashboard page you will get your App ID', 'In Dashboard page you will get your App ID', '2022-12-11 12:36:34', '2022-12-11 12:36:34'),
(1812, 'en', 'Area Wise Flat Shipping Cost', 'Area Wise Flat Shipping Cost', '2022-12-11 12:37:19', '2022-12-11 12:37:19'),
(1813, 'en', 'Seller Wise Flat Shipping Cost calulation: Fixed rate for each seller. If customers purchase 2 product from two seller shipping cost is calculated by addition of each seller flat shipping cost', 'Seller Wise Flat Shipping Cost calulation: Fixed rate for each seller. If customers purchase 2 Service from two seller shipping cost is calculated by addition of each seller flat shipping cost', '2022-12-11 12:37:19', '2023-02-20 15:07:21'),
(1814, 'en', 'Area Wise Flat Shipping Cost calulation: Fixed rate for each area. If customers purchase multiple products from one seller shipping cost is calculated by the customer shipping area. To configure area wise shipping cost go to ', 'Area Wise Flat Shipping Cost calulation: Fixed rate for each area. If customers purchase multiple services from one seller shipping cost is calculated by the customer shipping area. To configure area wise shipping cost go to', '2022-12-11 12:37:19', '2023-02-20 15:07:43'),
(1815, 'en', '1. Flat rate shipping cost is applicable if Flat rate shipping is enabled.', '1. Flat rate shipping cost is applicable if Flat rate shipping is enabled.', '2022-12-11 12:37:19', '2022-12-11 12:37:19'),
